<?php class CalificacionModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;} function obtenerTodas(){return $this->pdo->query("SELECT c.*,CONCAT(u.nombre,' ',u.apellido) estudiante,cu.nombre_curso,cu.codigo FROM calificaciones c JOIN inscripciones i ON i.id_inscripcion=c.id_inscripcion JOIN estudiantes e ON e.id_estudiante=i.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN cursos cu ON cu.id_curso=i.id_curso ORDER BY c.fecha DESC,c.id_calificacion DESC")->fetchAll();} function obtenerPorId($id){$s=$this->pdo->prepare('SELECT * FROM calificaciones WHERE id_calificacion=?');$s->execute([$id]);return $s->fetch();} function crear($d){$s=$this->pdo->prepare('INSERT INTO calificaciones(id_inscripcion,tipo,nota,observacion,fecha) VALUES(?,?,?,?,?)');return $s->execute([$d['id_inscripcion'],$d['tipo'],$d['nota'],$d['observacion'],$d['fecha']]);} function editar($id,$d){$s=$this->pdo->prepare('UPDATE calificaciones SET id_inscripcion=?,tipo=?,nota=?,observacion=?,fecha=? WHERE id_calificacion=?');return $s->execute([$d['id_inscripcion'],$d['tipo'],$d['nota'],$d['observacion'],$d['fecha'],$id]);} function eliminar($id){$s=$this->pdo->prepare('DELETE FROM calificaciones WHERE id_calificacion=?');return $s->execute([$id]);}}
